import{_ as n,a0 as r,w as p,s as u,ao as l,I as s,x as i,a1 as o,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const B=JSON.parse('{"title":"在 Linux 的 VirtualBox 中从 USB 驱动器启动 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 的 VirtualBox 中从 USB 驱动器启动 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 的 VirtualBox 中从 USB 驱动器启动 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 的 VirtualBox 中从 USB 驱动器启动 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230904 Boot From a USB Drive in VirtualBox in Linux","title":"在 Linux 的 VirtualBox 中从 USB 驱动器启动","tag":"202309","desc":""},"relativePath":"202309/20230904 Boot From a USB Drive in VirtualBox in Linux.md","filePath":"[post].md"}'),d={name:"202309/20230904 Boot From a USB Drive in VirtualBox in Linux.md"};function m(g,t,b,k,h,x){const e=r("Link");return p(),u("div",null,[t[26]||(t[26]=l('<h1 id="在-linux-的-virtualbox-中从-usb-驱动器启动" tabindex="-1">在 Linux 的 VirtualBox 中从 USB 驱动器启动 <a class="header-anchor" href="#在-linux-的-virtualbox-中从-usb-驱动器启动" aria-label="Permalink to “在 Linux 的 VirtualBox 中从 USB 驱动器启动”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/22/101826lcduo6etry9ep2rb.jpg" alt=""></p><blockquote><p>你可以在 VirtualBox 中的虚拟机上使用立付 Linux USB。这样可以省去重新启动主机的麻烦。</p></blockquote><p>你有一个 <ruby>立付<rt>Live</rt></ruby> Linux USB 吗？在当前系统上测试它的常用方法是重新启动，并在系统重新启动时选择从立付 USB 启动。</p><p>但这很烦人，因为你需要停止计算机上的工作并重新启动它。</p><p>一种干扰较小的方法是使用虚拟机。</p><p>是的，你可以使用 VirtualBox 从虚拟机中的 USB 启动。这样，你不必为了尝试而在 VM 中安装发行版，而是改用立付会话。</p><p>在本教程中，我将展示在 Linux 系统使用 VirtualBox 从 USB 驱动器启动的步骤。这需要花费一些时间和精力，但可以让你免于重启系统。</p><h3 id="在-linux-的-virtualbox-中从-usb-驱动器启动-1" tabindex="-1">在 Linux 的 VirtualBox 中从 USB 驱动器启动 <a class="header-anchor" href="#在-linux-的-virtualbox-中从-usb-驱动器启动-1" aria-label="Permalink to “在 Linux 的 VirtualBox 中从 USB 驱动器启动”">​</a></h3><p>由于这是针对高级用户的教程，因此我省略了你事先需要的几个步骤：</p>',10)),s("ul",null,[s("li",null,[t[1]||(t[1]=i("在 Linux 系统上 ",-1)),o(e,{href:"https://itsfoss.com/install-virtualbox-ubuntu/"},{default:a(()=>[...t[0]||(t[0]=[i("安装 VirtualBox",-1)])]),_:1})]),s("li",null,[t[3]||(t[3]=i("创建立付 Linux USB，最好 ",-1)),o(e,{href:"https://itsfoss.com/use-ventoy/"},{default:a(()=>[...t[2]||(t[2]=[i("使用 Ventoy",-1)])]),_:1})])]),t[27]||(t[27]=s("p",null,"本指南分为三个部分：",-1)),t[28]||(t[28]=s("ul",null,[s("li",null,"创建虚拟机磁盘文件"),s("li",null,"在 VM 中使用 USB 启动"),s("li",null,"删除虚拟机磁盘（可选）")],-1)),t[29]||(t[29]=s("p",null,"那么让我们从第一个开始。",-1)),t[30]||(t[30]=s("h4",{id:"步骤-1-创建虚拟机磁盘文件-vmdk",tabindex:"-1"},[i("步骤 1：创建虚拟机磁盘文件（VMDK） "),s("a",{class:"header-anchor",href:"#步骤-1-创建虚拟机磁盘文件-vmdk","aria-label":"Permalink to “步骤 1：创建虚拟机磁盘文件（VMDK）”"},"​")],-1)),s("p",null,[t[5]||(t[5]=i("首先，你需要识别 USB 驱动器的磁盘名称，为此，你需要 ",-1)),o(e,{href:"https://linuxhandbook.com/linux-list-disks/"},{default:a(()=>[...t[4]||(t[4]=[i("列出系统的驱动器",-1)])]),_:1}),t[6]||(t[6]=i("。",-1))]),t[31]||(t[31]=l('<p>为此，我将使用 lsblk 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lsblk</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/07/list-drives-in-Linux.png" alt=""></p><blockquote><p>🚧 确保使用不带任何数字的磁盘名称。就我而言，Ventoy 以 sdb1 命名，但我仍然只能使用 sdb。</p></blockquote><p>从上图中，你可以看到，Ventoy 列出了 <code>sdb11</code>，但你必须使用不带任何数字的名称。这意味着我必须只使用 <code>sdb</code>，否则，它会抛出错误。</p><p>找到驱动器名称后，使用以下命令中的 <code>VBoxManage</code> 命令来创建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo VBoxManage createmedium disk --filename=/path/to/rawdisk.vmdk --variant=RawDisk --format=VMDK --property RawDrive=/dev/sda</span></span></code></pre></div><p>在上面的命令中，将 <code>/path/to/rawdisk.vmdk</code> 替换为要保存文件的路径 ，将 <code>/dev/sda</code> 替换为目标驱动器。</p><p>就我而言，我想在我的主目录中创建一个名为 <code>IF.vmdk</code> 的文件，并且我的目标驱动器是 <code>/dev/sdb</code>，然后，我将使用以下命令：</p><blockquote><p>📋 你需要提供绝对路径来创建 vmdk 文件！</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo VBoxManage createmedium disk --filename=/home/sagar/IF.vmdk --variant=RawDisk --format=VMDK --property RawDrive=/dev/sdb</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/07/create-virtual-machine-disk-drive-for-virtualbox-to-boot-from-USB-drive-in-Linux.png" alt=""></p><p>最后，使用 <code>chmod</code> 命令更改权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chmod 777 Filename.vmdk</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/07/use-chmod-command-to-change-the-permissions.png" alt=""></p><h4 id="步骤-2-在-linux-的-virtualbox-中从-usb-启动" tabindex="-1">步骤 2：在 Linux 的 VirtualBox 中从 USB 启动 <a class="header-anchor" href="#步骤-2-在-linux-的-virtualbox-中从-usb-启动" aria-label="Permalink to “步骤 2：在 Linux 的 VirtualBox 中从 USB 启动”">​</a></h4><p>首先，从系统菜单中打开 VirtualBox，然后单击 “<ruby>新建<rt>New</rt></ruby>” 按钮。</p><p>在那里，为你的虚拟机命名并选择操作系统类型及其版本：</p><p><img src="https://itsfoss.com/content/images/2023/07/Create-VM-in-VirtualBox-to-boot-from-USB-in-Linux.png" alt=""></p><p>现在，单击 “<ruby>下一步<rt>Next</rt></ruby>” 按钮，它会要求你为虚拟机分配硬件资源：</p><p><img src="https://itsfoss.com/content/images/2023/07/allocate-RAM-and-cores-to-Vm-to-boot-from-USB-in-VirtualBox-in-Linux.png" alt=""></p><p>完成硬件资源分配后，单击“下一步”按钮。</p><p>在这里，你将找到创建或添加虚拟磁盘的选项。现在，请执行 3 个简单步骤：</p><ul><li>选择第二个选项 “<ruby>使用现有虚拟硬盘文件<rt>Use an Existing Virtual Hard Disk File</rt></ruby>”。</li><li>点击“文件”图标。</li><li>点击“<ruby>添加<rt>Add</rt></ruby>”按钮并选择你最近创建的以 <code>.vmdk</code> 结尾的文件。</li></ul><p><img src="https://itsfoss.com/content/images/2023/07/add-virtual-machine-disk-drive-in-VirtualBox-to-boot-from-USB-in-Linux.png" alt=""></p><p>选择文件后，它将显示文件的名称，选择它并点击 “<ruby>选择<rt>Choose</rt></ruby>” 选项：</p><p><img src="https://itsfoss.com/content/images/2023/07/select-the-vmdk-file.png" alt=""></p><p>它将向你显示已选择从中启动的文件。单击下一步，它将显示你所做的选择的摘要。</p><p>点击 “<ruby>完成<rt>Finish</rt></ruby>” 按钮：</p><p><img src="https://itsfoss.com/content/images/2023/07/Finish-the-VM-creation-to-boot-from-USB-in-VirtualBox-in-Linux.png" alt=""></p><p>就是这样！ 虚拟机已创建。</p><p>要启动虚拟机，首先选择虚拟机并单击启动按钮：</p><p><img src="https://itsfoss.com/content/images/2023/07/start-the-VM.png" alt=""></p><p>由于我的 USB 有 Ventoy，你可以看到，此处列出了多个发行版：</p><p><img src="https://itsfoss.com/content/images/2023/07/Boot-from-USB-in-VirtualBox-in-Linux.png" alt=""></p><p>很酷。是么？</p><h4 id="步骤-3-使用删除虚拟机及-vmdk-文件-可选" tabindex="-1">步骤 3：使用删除虚拟机及 vmdk 文件（可选） <a class="header-anchor" href="#步骤-3-使用删除虚拟机及-vmdk-文件-可选" aria-label="Permalink to “步骤 3：使用删除虚拟机及 vmdk 文件（可选）”">​</a></h4><p>当我在删除虚拟机后尝试删除 vmdk 文件时，当然，它被删除了，但每当我尝试创建具有相同名称的新文件时，它都会给我一个错误，说该文件已经存在！</p><p>因此，在这里，我将引导你了解如何删除虚拟机及 vmdk 文件。</p><p>首先，关闭虚拟机并将其删除。</p><p><img src="https://itsfoss.com/content/images/2023/07/Remove-VM-from-VirtualBox.png" alt=""></p>',41)),s("p",null,[t[8]||(t[8]=i("现在，如果你尝试 ",-1)),o(e,{href:"https://linuxhandbook.com/remove-files-directories/"},{default:a(()=>[...t[7]||(t[7]=[i("使用 rm 命令",-1)])]),_:1}),t[9]||(t[9]=i(" 并提升权限删除 vmdk 文件，你可以删除它（但这就是幻觉的开始）。",-1))]),t[32]||(t[32]=l('<p>例如，在这里，我删除了 <code>IF.vmdk</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rm IF.vmdk</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/07/use-rm-command-to-remove-vmdk-file.png" alt=""></p><p>现在，如果我尝试创建一个具有相同名称的新 vmdk 文件，则会出现错误，指出该文件已存在：</p><p><img src="https://itsfoss.com/content/images/2023/07/unable-to-create-vmdk-file-in-Linux--file-already-exist.png" alt=""></p><p>要删除 vmdk 文件，首先，你必须使用以下命令取消注册该文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo VBoxManage closemedium disk /path/to/MyDrive.vmdk</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/07/unregister-vmdk-file-in-Linux-to-remove-it.png" alt=""></p><p>完成后，你可以使用 <code>rm</code> 命令删除该文件，它将轻松删除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rm Filename.vmdk</span></span></code></pre></div><p>然后，如果你尝试创建具有相同文件名的 vmdk 文件，你可以这样做：</p><p><img src="https://itsfoss.com/content/images/2023/07/how-to-remove-the-vmdk-file-in-Linux.png" alt=""></p><p>这就行了！</p><h3 id="更多虚拟机技巧" tabindex="-1">更多虚拟机技巧 <a class="header-anchor" href="#更多虚拟机技巧" aria-label="Permalink to “更多虚拟机技巧”">​</a></h3><p>如果你正在寻找最快的 VM，可以使用 Qemu + KVM 的组合。我知道这听起来很复杂。</p><p>但为了更简单一些，我们制作了一份关于如何在 Ubuntu 上安装和使用 Qemu 的专门指南，包括启用共享文件夹、剪贴板和自动调整大小：</p>',16)),s("blockquote",null,[s("p",null,[s("strong",null,[o(e,{href:"https://itsfoss.com/qemu-ubuntu/"},{default:a(()=>[...t[10]||(t[10]=[i("如何在 Ubuntu 上安装和使用 Qemu",-1)])]),_:1})])])]),t[33]||(t[33]=s("p",null,"我希望本指南对你有所帮助。",-1)),t[34]||(t[34]=s("p",null,[s("em",null,"（题图：MJ/f74a3b33-2bcf-445b-8868-1dfc420f5b9d）")],-1)),t[35]||(t[35]=s("hr",null,null,-1)),s("p",null,[t[12]||(t[12]=i("via: ",-1)),o(e,{href:"https://itsfoss.com/virtualbox-boot-from-usb/"},{default:a(()=>[...t[11]||(t[11]=[i("https://itsfoss.com/virtualbox-boot-from-usb/",-1)])]),_:1})]),s("p",null,[t[17]||(t[17]=i("作者：",-1)),o(e,{href:"https://itsfoss.com/author/sagar/"},{default:a(()=>[...t[13]||(t[13]=[i("Sagar Sharma",-1)])]),_:1}),t[18]||(t[18]=i(" 选题：",-1)),o(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[14]||(t[14]=[i("lujun9972",-1)])]),_:1}),t[19]||(t[19]=i(" 译者：",-1)),o(e,{href:"https://github.com/geekpi"},{default:a(()=>[...t[15]||(t[15]=[i("geekpi",-1)])]),_:1}),t[20]||(t[20]=i(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[16]||(t[16]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[23]||(t[23]=i("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[21]||(t[21]=[i("LCTT",-1)])]),_:1}),t[24]||(t[24]=i(" 原创编译，",-1)),o(e,{href:"https://linux.cn/"},{default:a(()=>[...t[22]||(t[22]=[i("Linux中国",-1)])]),_:1}),t[25]||(t[25]=i(" 荣誉推出",-1))])])}const c=n(d,[["render",m]]);export{B as __pageData,c as default};
